-- Apply with Supabase SQL editor or `supabase db push`.
create extension if not exists pgcrypto;
create type public.app_role as enum ('student','teacher','admin');
create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text not null default '',bio text not null default '',role public.app_role not null default 'student',language text not null default 'kk' check(language in ('kk','ru','en')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.courses(id uuid primary key default gen_random_uuid(),teacher_id uuid not null references public.profiles,title text not null check(length(title) between 3 and 180),description text not null,category text not null,difficulty text not null check(difficulty in ('easy','medium','hard')),duration numeric not null check(duration>0 and duration<=1000),cover_url text,status text not null default 'draft' check(status in ('draft','published')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.enrollments(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,course_id uuid not null references public.courses on delete cascade,created_at timestamptz not null default now(),unique(user_id,course_id));
create table public.lessons(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses on delete cascade,title text not null,content text not null default '',material_path text,position integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.lesson_completions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,lesson_id uuid not null references public.lessons on delete cascade,created_at timestamptz not null default now(),unique(user_id,lesson_id));
create table public.assignments(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses on delete cascade,title text not null,description text not null,deadline timestamptz not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.submissions(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.assignments on delete cascade,user_id uuid not null references public.profiles on delete cascade,answer text not null default '',attachment_path text,grade numeric check(grade between 0 and 100),feedback text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(assignment_id,user_id));
create table public.documents(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,name text not null,detected_title text not null default '',path text not null unique,size integer not null check(size>0 and size<=10485760),mime_type text not null default '',hash text not null,text text not null check(length(text) between 3 and 500000),word_count integer not null,character_count integer not null,page_count integer,created_at timestamptz not null default now(),unique(user_id,hash));
create table public.document_analyses(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents on delete cascade,user_id uuid not null references public.profiles on delete cascade,language text not null,result jsonb not null,created_at timestamptz not null default now());
create table public.quizzes(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,document_id uuid references public.documents on delete cascade,course_id uuid references public.courses on delete cascade,title text not null,difficulty text not null check(difficulty in ('easy','medium','hard')),created_at timestamptz not null default now());
create table public.quiz_questions(id uuid primary key default gen_random_uuid(),quiz_id uuid not null references public.quizzes on delete cascade,position integer not null,question text not null,options jsonb not null check(jsonb_array_length(options)=4),correct_answer integer not null check(correct_answer between 0 and 3),explanation text not null,created_at timestamptz not null default now(),unique(quiz_id,position));
create table public.quiz_attempts(id uuid primary key default gen_random_uuid(),quiz_id uuid not null references public.quizzes on delete cascade,user_id uuid not null references public.profiles on delete cascade,answers jsonb not null,score integer not null check(score between 0 and 100),correct integer not null,total integer not null,seconds integer not null check(seconds>=0),created_at timestamptz not null default now());
create table public.calendar_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,title text not null,start_at timestamptz not null,end_at timestamptz not null check(end_at>=start_at),description text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,title text not null,body text not null default '',read boolean not null default false,created_at timestamptz not null default now());
create table public.ai_conversations(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,title text not null,document_id uuid references public.documents on delete set null,created_at timestamptz not null default now());
create table public.ai_messages(id uuid primary key default gen_random_uuid(),sequence bigint generated always as identity unique,conversation_id uuid not null references public.ai_conversations on delete cascade,user_id uuid not null references public.profiles on delete cascade,role text not null check(role in ('user','assistant')),content text not null check(length(content)<=30000),created_at timestamptz not null default now());
create table public.activity(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,kind text not null,created_at timestamptz not null default now());
create function public.current_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select coalesce(public.current_role()='admin',false)$$;
create function public.teaches(cid uuid) returns boolean language sql stable security definer set search_path=public as $$select public.is_admin() or exists(select 1 from public.courses where id=cid and teacher_id=auth.uid() and public.current_role()='teacher')$$;
create function public.enrolled(cid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.enrollments where course_id=cid and user_id=auth.uid())$$;
create function public.can_learn(cid uuid) returns boolean language sql stable security definer set search_path=public as $$select public.teaches(cid) or (public.enrolled(cid) and exists(select 1 from public.courses where id=cid and status='published'))$$;
create function public.create_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name) values(new.id,left(coalesce(new.raw_user_meta_data->>'full_name',''),120));return new;end$$;
create trigger auth_profile after insert on auth.users for each row execute function public.create_profile();
create function public.guard_profile() returns trigger language plpgsql set search_path=public as $$begin if new.role<>old.role and current_user not in ('postgres','supabase_admin') and not public.is_admin() then raise exception 'role changes require administrator';end if;return new;end$$;
create trigger guard_profile before update on public.profiles for each row execute function public.guard_profile();
create function public.updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
do $$declare tab text;begin foreach tab in array array['profiles','courses','lessons','assignments','submissions','calendar_events'] loop execute format('create trigger updated_at before update on public.%I for each row execute function public.updated_at()',tab);end loop;end$$;
-- Trigger protects grades even though the student is allowed to update their answer.
create function public.guard_submission() returns trigger language plpgsql set search_path=public as $$declare cid uuid;due timestamptz;begin select course_id,deadline into cid,due from public.assignments where id=new.assignment_id;if tg_op='UPDATE' and (new.user_id<>old.user_id or new.assignment_id<>old.assignment_id) then raise exception 'immutable ownership';end if;if not public.teaches(cid) then if new.user_id<>auth.uid() or not public.can_learn(cid) or due<now() then raise exception 'submission forbidden';end if;if tg_op='INSERT' then if new.grade is not null or new.feedback<>'' then raise exception 'cannot self grade';end if;elsif new.grade is distinct from old.grade or new.feedback is distinct from old.feedback then raise exception 'cannot self grade';end if;else if tg_op='UPDATE' and (new.answer<>old.answer or new.attachment_path is distinct from old.attachment_path) then raise exception 'cannot alter student work';end if;end if;return new;end$$;
create trigger guard_submission before insert or update on public.submissions for each row execute function public.guard_submission();
do $$declare tab text;begin foreach tab in array array['profiles','courses','enrollments','lessons','lesson_completions','assignments','submissions','documents','document_analyses','quizzes','quiz_questions','quiz_attempts','calendar_events','notifications','ai_conversations','ai_messages','activity'] loop execute format('alter table public.%I enable row level security',tab);end loop;end$$;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin() or exists(select 1 from public.enrollments e where e.user_id=profiles.id and public.teaches(e.course_id)));
create policy profile_edit on public.profiles for update to authenticated using(id=auth.uid() or public.is_admin()) with check(id=auth.uid() or public.is_admin());
create policy course_read on public.courses for select to authenticated using(status='published' or public.teaches(id));
create policy course_insert on public.courses for insert to authenticated with check((teacher_id=auth.uid() and public.current_role() in ('teacher','admin')) or public.is_admin());
create policy course_update on public.courses for update to authenticated using(public.teaches(id)) with check((teacher_id=auth.uid() and public.current_role() in ('teacher','admin')) or public.is_admin());
create policy course_delete on public.courses for delete to authenticated using(public.teaches(id));
create policy enrollment_read on public.enrollments for select to authenticated using(user_id=auth.uid() or public.teaches(course_id));
create policy enrollment_insert on public.enrollments for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.courses where id=course_id and status='published'));
create policy enrollment_delete on public.enrollments for delete to authenticated using(user_id=auth.uid() or public.teaches(course_id));
create policy lesson_read on public.lessons for select to authenticated using(public.can_learn(course_id));
create policy lesson_write on public.lessons for all to authenticated using(public.teaches(course_id)) with check(public.teaches(course_id));
create policy completion_read on public.lesson_completions for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.lessons where id=lesson_id and public.teaches(course_id)));
create policy completion_insert on public.lesson_completions for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.lessons where id=lesson_id and public.can_learn(course_id)));
create policy assignment_read on public.assignments for select to authenticated using(public.can_learn(course_id));
create policy assignment_write on public.assignments for all to authenticated using(public.teaches(course_id)) with check(public.teaches(course_id));
create policy submission_read on public.submissions for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.assignments where id=assignment_id and public.teaches(course_id)));
create policy submission_insert on public.submissions for insert to authenticated with check(user_id=auth.uid());
create policy submission_update on public.submissions for update to authenticated using(user_id=auth.uid() or exists(select 1 from public.assignments where id=assignment_id and public.teaches(course_id))) with check(user_id=auth.uid() or exists(select 1 from public.assignments where id=assignment_id and public.teaches(course_id)));
do $$declare tab text;begin foreach tab in array array['documents','calendar_events','ai_conversations'] loop execute format('create policy owner_all on public.%I for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid())',tab);end loop;end$$;
-- AI writes and quiz scores only through guarded RPCs; no direct client insert policies.
create policy analyses_read on public.document_analyses for select to authenticated using(user_id=auth.uid());
create policy quizzes_read on public.quizzes for select to authenticated using(user_id=auth.uid());
create policy attempts_read on public.quiz_attempts for select to authenticated using(user_id=auth.uid());
create policy notifications_read on public.notifications for select to authenticated using(user_id=auth.uid());
create policy notifications_update on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy messages_read on public.ai_messages for select to authenticated using(user_id=auth.uid());
create policy activity_read on public.activity for select to authenticated using(user_id=auth.uid() or public.is_admin());
-- Quiz answers are never selectable directly, including by their owner.
create function public.get_quiz(qid uuid) returns jsonb language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from public.quizzes where id=qid and user_id=auth.uid()) then raise exception 'forbidden';end if;return (select coalesce(jsonb_agg(jsonb_build_object('id',id,'question',question,'options',options,'position',position) order by position),'[]') from public.quiz_questions where quiz_id=qid);end$$;
-- Transaction 1: persist complete generated quiz atomically. API uses the authenticated JWT.
create function public.save_quiz(doc uuid,cid uuid,quiz_title text,level text,questions jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare qid uuid;item jsonb;pos integer:=0;begin if auth.uid() is null then raise exception 'unauthorized';end if;if doc is not null and not exists(select 1 from public.documents where id=doc and user_id=auth.uid()) then raise exception 'forbidden';end if;if cid is not null and not public.can_learn(cid) then raise exception 'forbidden';end if;if doc is null and cid is null then raise exception 'source required';end if;if jsonb_array_length(questions) not in (5,10,15,20) then raise exception 'invalid quiz';end if;insert into public.quizzes(user_id,document_id,course_id,title,difficulty) values(auth.uid(),doc,cid,quiz_title,level) returning id into qid;for item in select * from jsonb_array_elements(questions) loop insert into public.quiz_questions(quiz_id,position,question,options,correct_answer,explanation) values(qid,pos,item->>'question',item->'options',(item->>'correct_answer')::int,item->>'explanation');pos:=pos+1;end loop;return qid;end$$;
-- Transaction 2: scoring and attempt persistence. Never trust a submitted score.
create function public.submit_quiz(qid uuid,choices jsonb,elapsed integer) returns jsonb language plpgsql security definer set search_path=public as $$declare correct_count integer:=0;question_count integer;points integer;details jsonb;begin if not exists(select 1 from public.quizzes where id=qid and user_id=auth.uid()) then raise exception 'forbidden';end if;select count(*) into question_count from public.quiz_questions where quiz_id=qid;if jsonb_array_length(choices)<>question_count or elapsed<0 or exists(select 1 from jsonb_array_elements_text(choices) a where a !~ '^[0-3]$') then raise exception 'invalid answers';end if;select count(*) into correct_count from public.quiz_questions where quiz_id=qid and correct_answer=(choices->>position)::int;points:=round(100.0*correct_count/question_count);insert into public.quiz_attempts(quiz_id,user_id,answers,score,correct,total,seconds) values(qid,auth.uid(),choices,points,correct_count,question_count,elapsed);select jsonb_agg(jsonb_build_object('question',question,'options',options,'correct_answer',correct_answer,'explanation',explanation) order by position) into details from public.quiz_questions where quiz_id=qid;return jsonb_build_object('correct',correct_count,'total',question_count,'score',points,'questions',details,'seconds',elapsed);end$$;
create function public.save_analysis(doc uuid,lang text,analysis jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare aid uuid;begin if not exists(select 1 from public.documents where id=doc and user_id=auth.uid()) then raise exception 'forbidden';end if;insert into public.document_analyses(user_id,document_id,language,result) values(auth.uid(),doc,lang,analysis) returning id into aid;return aid;end$$;
create function public.save_chat(cid uuid,prompt text,answer text) returns void language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from public.ai_conversations where id=cid and user_id=auth.uid()) then raise exception 'forbidden';end if;insert into public.ai_messages(conversation_id,user_id,role,content) values(cid,auth.uid(),'user',prompt),(cid,auth.uid(),'assistant',answer);end$$;
-- RPCs validate ownership; authenticated clients may create their own quiz content,
-- but cannot write a score or read answer keys before submission.
revoke all on all functions in schema public from public, anon;
grant execute on all functions in schema public to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('documents','documents',false,10485760,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/plain']),('materials','materials',false,10485760,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/plain']);
create policy document_storage_owner on storage.objects for all to authenticated using(bucket_id='documents' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='documents' and (storage.foldername(name))[1]=auth.uid()::text);
create policy material_read on storage.objects for select to authenticated using(bucket_id='materials' and public.can_learn(((storage.foldername(name))[1])::uuid));
create policy material_write on storage.objects for all to authenticated using(bucket_id='materials' and public.teaches(((storage.foldername(name))[1])::uuid)) with check(bucket_id='materials' and public.teaches(((storage.foldername(name))[1])::uuid));
create index courses_teacher on public.courses(teacher_id);
create index enrollments_course on public.enrollments(course_id);
create index lessons_course on public.lessons(course_id,position);
create index assignments_course on public.assignments(course_id,deadline);
create index submissions_user on public.submissions(user_id);
create index documents_owner on public.documents(user_id,created_at desc);
create index attempts_user on public.quiz_attempts(user_id,created_at desc);
create index messages_conversation on public.ai_messages(conversation_id,sequence);
create index events_owner on public.calendar_events(user_id,start_at);
create index completions_lesson on public.lesson_completions(lesson_id);
create index questions_quiz on public.quiz_questions(quiz_id,position);
-- Instructors can read only files actually attached to their course submissions.
create policy submission_attachment_read on storage.objects for select to authenticated using(bucket_id='documents' and exists(select 1 from public.submissions s join public.assignments a on a.id=s.assignment_id where s.attachment_path=storage.objects.name and public.teaches(a.course_id)));
create function public.guard_attachment() returns trigger language plpgsql set search_path=public as $$begin if new.attachment_path is not null and split_part(new.attachment_path,'/',1)<>new.user_id::text then raise exception 'invalid attachment owner';end if;return new;end$$;
create trigger guard_attachment before insert or update on public.submissions for each row execute function public.guard_attachment();
create table public.ai_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,created_at timestamptz not null default now());
alter table public.ai_requests enable row level security;
create index ai_requests_user_time on public.ai_requests(user_id,created_at);
create function public.reserve_ai_request() returns boolean language plpgsql security definer set search_path=public as $$begin if auth.uid() is null then raise exception 'unauthorized';end if;perform pg_advisory_xact_lock(hashtext(auth.uid()::text));if (select count(*) from public.ai_requests where user_id=auth.uid() and created_at>now()-interval '1 minute')>=10 then return false;end if;insert into public.ai_requests(user_id) values(auth.uid());delete from public.ai_requests where user_id=auth.uid() and created_at<now()-interval '1 day';return true;end$$;
revoke all on function public.reserve_ai_request() from public,anon;
grant execute on function public.reserve_ai_request() to authenticated;
revoke all on function public.guard_attachment() from public,anon;
-- Trusted activity records: no browser insert policy.
create function public.record_activity() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.activity(user_id,kind) values(new.user_id,tg_table_name);return new;end$$;
do $$declare tab text;begin foreach tab in array array['enrollments','lesson_completions','submissions','quiz_attempts','documents'] loop execute format('create trigger activity_insert after insert on public.%I for each row execute function public.record_activity()',tab);end loop;end$$;
create function public.assignment_notification() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.notifications(user_id,title,body) select e.user_id,new.title,case p.language when 'kk' then 'Жаңа тапсырма қосылды.' when 'ru' then 'Добавлено новое задание.' else 'A new assignment is available.' end from public.enrollments e join public.profiles p on p.id=e.user_id where e.course_id=new.course_id;return new;end$$;
create trigger assignment_notification after insert on public.assignments for each row execute function public.assignment_notification();
revoke all on function public.record_activity(),public.assignment_notification() from public,anon;
-- Three reusable aggregate queries execute under the caller's RLS context.
create function public.course_progress() returns table(course_id uuid,total_lessons bigint,completed_lessons bigint,progress integer) language sql stable security invoker set search_path=public as $$
select e.course_id,count(distinct l.id),count(distinct lc.lesson_id),case when count(distinct l.id)=0 then 0 else round(100.0*count(distinct lc.lesson_id)/count(distinct l.id))::int end
from public.enrollments e left join public.lessons l on l.course_id=e.course_id left join public.lesson_completions lc on lc.lesson_id=l.id and lc.user_id=auth.uid() where e.user_id=auth.uid() group by e.course_id$$;
create function public.grade_distribution() returns table(bucket integer,count bigint) language sql stable security invoker set search_path=public as $$
select least(9,floor(score/10))::int*10,count(*) from (select grade as score from public.submissions where user_id=auth.uid() and grade is not null union all select score::numeric from public.quiz_attempts where user_id=auth.uid()) scores group by 1 order by 1$$;
create function public.weekly_learning_activity() returns table(day date,count bigint) language sql stable security invoker set search_path=public as $$
select d::date,count(l.id) from generate_series(current_date-6,current_date,interval '1 day') d left join public.lesson_completions l on l.created_at::date=d::date and l.user_id=auth.uid() group by 1 order by 1$$;
revoke all on function public.course_progress(),public.grade_distribution(),public.weekly_learning_activity() from public,anon;
grant execute on function public.course_progress(),public.grade_distribution(),public.weekly_learning_activity() to authenticated;
